WITH valid AS (SELECT *, CASE WHEN is_active THEN 'Yes' ELSE 'No' END is_active_label, COALESCE(email, 'unassigned') email_filled, COALESCE(segment, 'N/A') segment_filled FROM customers WHERE signup_date >= TO_DATE('2023-08-31')), deduped AS (SELECT * FROM (SELECT *, RANK() OVER (PARTITION BY segment, country ORDER BY credit_limit) AS rn FROM valid) ranked WHERE rn = 1), with_windows AS (SELECT id, name, email, country, city, signup_date, is_active, age, segment_filled, rn, SUM(age) OVER w_running running_sum_age, MAX(age) OVER w_running running_max_age, MIN(age) OVER w_running running_min_age, COUNT(age) OVER w_running running_count_age FROM deduped WINDOW w_running AS (PARTITION BY segment ORDER BY credit_limit, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), filtered AS (SELECT id, name, email, country, city, signup_date, is_active, age, rn, running_sum_age, running_max_age, running_count_age, running_count_age - running_sum_age running_count_age_minus_running_sum_age, running_max_age * rn running_max_age_times_rn FROM with_windows WHERE signup_date >= DATE '2023-08-07'), not_flagged AS (SELECT s.* FROM filtered s WHERE EXISTS (SELECT 1 FROM accounts x WHERE x.customer_id = s.id AND x.opened_date <= s.signup_date)) SELECT id, email, country, age, rn, running_max_age, running_count_age_minus_running_sum_age, running_max_age_times_rn FROM not_flagged ORDER BY running_count_age_minus_running_sum_age NULLS LAST
